def solve():
    n = 230
    max_m = 0
    # Let's try to find the maximum m such that there exist k, p
    # satisfying the conditions.

    for m in range(1, n + 1):
        found = False
        limit_kp = n**2 / (m + n)
        limit_k = (n - m) / 2

        for k in range(int(limit_k) + 1, int(limit_kp) + 1):
            if k >= n: continue
            for p in range(1, int(limit_kp) + 1):
                if p >= n: continue

                # Condition for R'_i to sum to n^2/2
                if k * (m + n) < n**2 < 2 * k * n + (n - k) * (n - m):
                    # Condition for C'_j to sum to n^2/2
                    if p * (m + n) < n**2 < 2 * p * n + (n - p) * (n - m):
                        # Condition for row/column sums
                        if k * (m + n) / 2 < p * k + (n - p) * min(k, (n - m) / 2):
                            found = True
                            break
            if found: break
        if found:
            max_m = max(max_m, m)
    return max_m

