        limit_kp = n**2 / (m + n)
        limit_k = (n - m) / 2

        k_min = int(limit_k) + 1
        k_max = min(n - 1, int((n**2 - 1) / (m + n)))
        p_max = min(n - 1, int((n**2 - 1) / (m + n)))

        if k_min <= k_max and p_max >= 1:
            for k in range(k_min, k_max + 1):
                p = p_max
                if k * (m + n) / 2 < p * k + (n - p) * min(k, (n - m) / 2):
                    found = True
                    break
        if found:
            ans = max(ans, m)
    return ans

